      cat_S: "S – standard rate", cat_Z: "Z – zero rated", cat_E: "E – exempt", cat_AE: "AE – reverse charge", cat_K: "K – intra-community", cat_G: "G – export",
      ac_kind: "Type", ac_allowance: "Discount", ac_charge: "Surcharge", ac_mode: "Calculation", ac_amount: "Amount", ac_percent: "Percent of net", ac_value: "Value", ac_reason: "Reason", ac_rate: "VAT % of base", add_ac: "+ Discount / surcharge", ac_hint: "Applied before VAT (BG-20 / BG-21).",
